## webhook_auth tests — known-answer vectors for the single MAC definition site.
##
## The vectors are external, not generated by the code under test. The hex form
## was computed independently with:
##
##   printf '%s' '{"events":[]}' | \
##     openssl dgst -sha256 -hmac 'test-channel-secret' -binary | xxd -p -c 256
##
## and the base64 form with the same command using `| base64`.

import std/unittest
import donkey/core/security/webhook_auth

const
  KatSecret   = "test-channel-secret"
  KatBody     = """{"events":[]}"""
  KatBase64   = "sKRrt+MTE71nWWZPaYrvYSdH9JGlgckmBidZxDuPgPc="
  KatHex      = "b0a46bb7e31313bd6759664f698aef612747f491a581c926062759c43b8f80f7"
  ## printf '%s' '{"post_type":"message"}' | openssl dgst -sha1 -hmac 'onebot-secret'
  KatSha1Secret = "onebot-secret"
  KatSha1Body   = """{"post_type":"message"}"""
  KatSha1Hex    = "19a20b08a7fa2632968ebb5ca3efca2111a59eab"

proc runTests*() =
  suite "hmacSha256 — external known-answer vectors":
    test "base64 form matches the LINE/DingTalk vector":
      check hmacSha256Base64(KatSecret, KatBody) == KatBase64

    test "hex form matches the independently computed digest":
      check hmacSha256Hex(KatSecret, KatBody) == KatHex

    test "the body is signed byte for byte, not normalized":
      check hmacSha256Base64(KatSecret, KatBody & "\n") != KatBase64

  suite "hmacSha1 — OneBot v11 X-Signature":
    test "hex form matches the independently computed digest":
      check hmacSha1Hex(KatSha1Secret, KatSha1Body) == KatSha1Hex

    test "a different secret gives a different digest":
      check hmacSha1Hex("other", KatSha1Body) != KatSha1Hex

  suite "safeEquals":
    test "equal strings compare true":
      check safeEquals(KatBase64, KatBase64)
      check safeEquals("", "")

    test "a same-length mismatch compares false":
      var wrong = KatBase64
      wrong[0] = if wrong[0] == 'A': 'B' else: 'A'
      check not safeEquals(wrong, KatBase64)

    test "different lengths compare false without indexing":
      check not safeEquals("", KatBase64)
      check not safeEquals(KatBase64, KatBase64[0 ..< 10])

when isMainModule:
  runTests()
